"""A minimal ebook module (core kit + blocks, two books with their kits) that follows references/14-module-layout.md."""
from pathlib import Path

KIT = ("example-label", "answer-line")

CORE = {
    "index.ts": "export { EbookPage } from './ebook-page'\nexport { blockSchema } from './core/model/blocks'\nexport type { Block } from './core/model/blocks'\nexport { BOOK_IDS } from './books/registry'\n",
    "ebook-page.tsx": "import { lazy } from 'react'\nimport { BOOKS } from './books/registry'\nimport { BookPage } from './core/views/book-page'\nexport function EbookPage({ book }: { book: keyof typeof BOOKS }) { const Style = lazy(BOOKS[book]); return <BookPage style={Style} /> }\n",
    "core/contracts.ts": "import type { Kit } from './kit/contract'\nexport interface BookStyle { id: string; kit: Kit }\n",
    "core/kit/contract.ts": "import type { ComponentType, ReactNode } from 'react'\nexport const KIT = ['example-label', 'answer-line'] as const\nexport interface Kit { ExampleLabel: ComponentType<{ children: ReactNode }>; AnswerLine: ComponentType<{ lead?: 'arrow' }> }\n",
    "core/kit/use-kit.ts": "import { createContext, useContext } from 'react'\nimport type { Kit } from './contract'\nexport const KitContext = createContext<Kit | null>(null)\nexport const useKit = () => useContext(KitContext) as Kit\n",
    "core/kit/reading/example-label/example-label.tsx": "export function ExampleLabel({ children }: { children: React.ReactNode }) { return <span data-kit=\"example-label\" className=\"rounded-full bg-primary px-3 text-sm text-primary-foreground\">{children}</span> }\n",
    "core/kit/reading/answer-line/answer-line.tsx": "export function AnswerLine({ lead }: { lead?: 'arrow' }) { return <span data-kit=\"answer-line\" className=\"flex items-end gap-2\">{lead === 'arrow' ? <span data-kit-part=\"lead\">→</span> : null}<span data-kit-part=\"rule\" className=\"h-px flex-1 scale-y-50 bg-current\" /></span> }\n",
    "core/model/blocks.ts": "import { z } from 'zod'\nexport const blockSchema = z.object({ id: z.string(), kind: z.string() })\nexport type Block = z.infer<typeof blockSchema>\n",
    "core/model/ids.ts": "export const questionId = (n: number) => `q-${n}`\n",
    "core/model/scale.ts": "export const pt = (n: number) => `calc(var(--wb-pt) * ${n})`\n",
    "core/views/book-page.tsx": "import { PageView } from './page-view'\nexport function BookPage({ style }: { style: unknown }) { return <div data-book=\"x\" data-view=\"reading\" className=\"@container/book\"><PageView /></div> }\n",
    "core/views/page-view.tsx": "import { ExampleBox } from '../blocks/example-box/example-box'\nexport function PageView() { return <ExampleBox id=\"q-1\" /> }\n",
    "core/views/reader-view.ts": "import { createContext } from 'react'\nexport const ReaderView = createContext<'sheet' | 'reading'>('reading')\n",
    "core/blocks/example-box/example-box.tsx": "import { useKit } from '../../kit/use-kit'\nexport function ExampleBox({ id }: { id: string }) {\n  const { ExampleLabel, AnswerLine } = useKit()\n  return <section data-block={id} className=\"wb-example\"><ExampleLabel>{'ex'}</ExampleLabel><AnswerLine lead=\"arrow\" /></section>\n}\n",
    "books/registry.ts": "export const BOOKS = { 'vitamin-1': () => import('./vitamin-1'), 'sejong-4a': () => import('./sejong-4a') }\nexport const BOOK_IDS = Object.keys(BOOKS)\n",
}


def book_files(book: str, colour: str) -> dict[str, str]:
    files = {
        f"books/{book}/index.ts": "import type { BookStyle } from '../../core/contracts'\nimport { ExampleLabel } from './kit/example-label/example-label'\nimport { AnswerLine } from './kit/answer-line/answer-line'\nconst style = { id: '" + book + "', kit: { ExampleLabel, AnswerLine } } satisfies BookStyle\nexport default style\n",
        f"books/{book}/model/tokens.ts": "export const LABEL = { height: 13.6, radius: 6.8 } as const\n",
        f"books/{book}/styles/palette.css": f"/* GENERATED by pdfmeasure palette: colours measured from the PDF. Do not edit by hand. */\n[data-book={book}] {{ --wb-green: {colour}; }}\n",
        f"books/{book}/styles/sheet.css": f"[data-book={book}][data-view=sheet] .wb-sheet {{ container-type: inline-size; --wb-pt: calc(100cqw / 532.913); }}\n",
        f"books/{book}/kit/example-label/example-label.tsx": "import { LABEL } from '../../model/tokens'\nimport { pt } from '../../../../core/model/scale'\nexport function ExampleLabel({ children }: { children: React.ReactNode }) {\n  return <span data-kit=\"example-label\" className=\"wb-label\" style={{ '--label-h': pt(LABEL.height) }}>{children}</span>\n}\n",
        f"books/{book}/kit/example-label/example-label.css": f"[data-book={book}][data-view=sheet] .wb-label {{ display: inline-flex; align-items: center; height: var(--label-h); }}\n",
        f"books/{book}/kit/answer-line/answer-line.tsx": "export function AnswerLine({ lead }: { lead?: 'arrow' }) {\n  return <span data-kit=\"answer-line\" className=\"wb-answer\">{lead === 'arrow' ? <span data-kit-part=\"lead\" className=\"wb-lead\">→</span> : null}<svg data-kit-part=\"rule\" className=\"wb-rule\" viewBox=\"0 0 100 1\"><line x1=\"0\" y1=\"0.5\" x2=\"100\" y2=\"0.5\" stroke=\"currentColor\" strokeWidth=\"0.3\" /></svg></span>\n}\n",
        f"books/{book}/kit/answer-line/answer-line.css": f"[data-book={book}][data-view=sheet] .wb-answer {{ display: flex; align-items: flex-end; }}\n",
        f"books/{book}/kit/answer-line/answer-line.test.tsx": "import { FIXTURE } from '../../fixtures/pages'\nit('renders', () => { expect(FIXTURE).toBeTruthy() })\n",
        f"books/{book}/fixtures/pages.ts": "export const FIXTURE = { id: 'q-1' }\n",
    }
    return files


def make_module(root: Path) -> Path:
    module = root / "ebook"
    files = {**CORE, **book_files("vitamin-1", "#45a665"), **book_files("sejong-4a", "#8fc11c")}
    for relative, text in files.items():
        path = module / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
    return module
